    cols = len(matrix[0])
    first_row_has_zero = any(matrix[0][j] == 0 for j in range(cols))
    first_col_has_zero = any(matrix[i][0] == 0 for i in range(rows))

    for i in range(1, rows):                                               # use row 0 and column 0 themselves as marker flags
        for j in range(1, cols):
            if matrix[i][j] == 0:
                matrix[i][0] = 0                                            # mark this row as needing zeroing
                matrix[0][j] = 0                                            # mark this column as needing zeroing

    for i in range(1, rows):                                               # apply the markers to zero out the interior
        for j in range(1, cols):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0

    if first_row_has_zero:                                                 # handle row 0 and column 0 last, using the flags saved at the start
        for j in range(cols):
            matrix[0][j] = 0
    if first_col_has_zero:
        for i in range(rows):
            matrix[i][0] = 0
    return matrix


